package com.rork.vitahero.data

import android.content.Intent
import io.github.jan.supabase.SupabaseClient
import io.github.jan.supabase.createSupabaseClient
import io.github.jan.supabase.auth.Auth
import io.github.jan.supabase.auth.FlowType
import io.github.jan.supabase.postgrest.Postgrest

/**
 * Singleton Supabase client with Auth + Postgrest.
 * Auth sessions are persisted automatically via EncryptedSharedPreferences on Android.
 */
object VitaSupabase {
    private var _client: SupabaseClient? = null

    val client: SupabaseClient
        get() {
            val c = _client
            if (c != null) return c
            val url = Config.EXPO_PUBLIC_SUPABASE_URL
            val key = Config.EXPO_PUBLIC_SUPABASE_ANON_KEY
            val newClient = createSupabaseClient(
                supabaseUrl = url,
                supabaseKey = key,
            ) {
                install(Auth) {
                    flowType = FlowType.PKCE
                    scheme = "vitahero"
                    host = "auth"
                }
                install(Postgrest)
            }
            _client = newClient
            return newClient
        }

    /** Call from MainActivity.onCreate to handle deeplinks (OTP verification, OAuth). */
    fun handleDeeplinks(intent: Intent) {
        client.auth.handleDeeplinks(intent)
    }

    /** Release resources. Call from Application.onTerminate or never (singleton lifetime). */
    fun close() {
        _client?.close()
        _client = null
    }
}

