{"name":"enable-phone-auth-and-link-profiles","sql":"-- Enable phone auth provider (required for phone OTP)
-- This updates the auth configuration to allow phone sign-ins
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.tables 
    WHERE table_schema = 'auth' AND table_name = 'users'
  ) THEN
    -- Phone provider doesn't need explicit enabling in the DB;
    -- it's controlled via the GoTrue configuration.
    -- This migration ensures the profiles table is ready for native auth.
    RAISE NOTICE 'Auth schema exists, proceeding with profile updates';
  END IF;
END $$;

-- Add user_id UUID column to profiles to link with auth.users
ALTER TABLE IF EXISTS public.profiles 
  ADD COLUMN IF NOT EXISTS user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE;

-- Create index on user_id for fast lookups
CREATE INDEX IF NOT EXISTS idx_profiles_user_id ON public.profiles(user_id);

-- Add user_id to kids table for RLS
ALTER TABLE IF EXISTS public.kids 
  ADD COLUMN IF NOT EXISTS user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE;
CREATE INDEX IF NOT EXISTS idx_kids_user_id ON public.kids(user_id);

-- Add user_id to appointments
ALTER TABLE IF EXISTS public.appointments 
  ADD COLUMN IF NOT EXISTS user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE;
CREATE INDEX IF NOT EXISTS idx_appointments_user_id ON public.appointments(user_id);

-- Add user_id to camps
ALTER TABLE IF EXISTS public.camps 
  ADD COLUMN IF NOT EXISTS user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE;
CREATE INDEX IF NOT EXISTS idx_camps_user_id ON public.camps(user_id);

-- Add user_id to meal_items
ALTER TABLE IF EXISTS public.meal_items 
  ADD COLUMN IF NOT EXISTS user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE;
CREATE INDEX IF NOT EXISTS idx_meal_items_user_id ON public.meal_items(user_id);

-- Add user_id to growth_points
ALTER TABLE IF EXISTS public.growth_points 
  ADD COLUMN IF NOT EXISTS user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE;
CREATE INDEX IF NOT EXISTS idx_growth_points_user_id ON public.growth_points(user_id);

-- Add user_id to streaks
