CREATE POLICY "Users can insert own meals" ON public.meal_items
  FOR INSERT WITH CHECK (auth.uid() = user_id);
DROP POLICY IF EXISTS "Users can update own meals" ON public.meal_items;
CREATE POLICY "Users can update own meals" ON public.meal_items
  FOR UPDATE USING (auth.uid() = user_id);

-- Growth points
DROP POLICY IF EXISTS "Users can read own growth points" ON public.growth_points;
CREATE POLICY "Users can read own growth points" ON public.growth_points
  FOR SELECT USING (auth.uid() = user_id);
DROP POLICY IF EXISTS "Users can insert own growth points" ON public.growth_points;
CREATE POLICY "Users can insert own growth points" ON public.growth_points
  FOR INSERT WITH CHECK (auth.uid() = user_id);

-- Streaks
DROP POLICY IF EXISTS "Users can read own streaks" ON public.streaks;
CREATE POLICY "Users can read own streaks" ON public.streaks
  FOR SELECT USING (auth.uid() = user_id);
DROP POLICY IF EXISTS "Users can insert own streaks" ON public.streaks;
CREATE POLICY "Users can insert own streaks" ON public.streaks
  FOR INSERT WITH CHECK (auth.uid() = user_id);
DROP POLICY IF EXISTS "Users can update own streaks" ON public.streaks;
CREATE POLICY "Users can update own streaks" ON public.streaks
  FOR UPDATE USING (auth.uid() = user_id);

-- Co-parents
DROP POLICY IF EXISTS "Users can read own co-parents" ON public.co_parents;
CREATE POLICY "Users can read own co-parents" ON public.co_parents
  FOR SELECT USING (auth.uid() = user_id);
DROP POLICY IF EXISTS "Users can insert own co-parents" ON public.co_parents;
CREATE POLICY "Users can insert own co-parents" ON public.co_parents
  FOR INSERT WITH CHECK (auth.uid() = user_id);

-- Auto-create profile on signup (via trigger on auth.users)
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER SET search_path = public
AS $$
BEGIN
  INSERT INTO public.profiles (id, user_id, name, phone)
  VALUES (
    COALESCE(NEW.raw_user_meta_data ->> 'phone', NEW.email, NEW.id::text),
    NEW.id,
    COALESCE(NEW.raw_user_meta_data ->> 'name', ''),
    NEW.phone
  )
  ON CONFLICT (id) DO UPDATE SET user_id = NEW.id;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();"}

