/**
 * Auth screen with real Supabase Auth:
 * - Email + Password (sign up / sign in)
 * - Phone OTP (sends real SMS via Supabase)
 */
@Composable
fun AuthScreen(
    onContinueWithPhone: (phone: String) -> Unit,
    onContinueWithEmail: (email: String, name: String) -> Unit,
    isLoading: Boolean = false,
    authError: String? = null
) {
    var isLogin by remember { mutableStateOf(true) }
    var authMethod by remember { mutableStateOf<AuthMethod>(AuthMethod.EMAIL) }
    var email by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }
    var name by remember { mutableStateOf("") }
    var phone by remember { mutableStateOf("") }
    var passwordVisible by remember { mutableStateOf(false) }
    val scope = rememberCoroutineScope()

    Column(
        Modifier
            .fillMaxSize()
            .background(MaterialTheme.colorScheme.background)
            .windowInsetsPadding(WindowInsets.systemBars)
            .verticalScroll(rememberScrollState())
            .padding(horizontal = 24.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Spacer(Modifier.height(40.dp))

        // Logo
        Box(
            Modifier
                .size(72.dp)
                .clip(RoundedCornerShape(22.dp))
                .background(Brush.linearGradient(listOf(HeroGreen, HeroBlue))),
            contentAlignment = Alignment.Center
        ) {
            Icon(Icons.Outlined.Shield, contentDescription = null, tint = Color.White, modifier = Modifier.size(38.dp))
        }
        Spacer(Modifier.height(16.dp))
        Text("VitaHero", style = MaterialTheme.typography.headlineLarge, fontWeight = FontWeight.Bold)
        Text(
            t(S.appSubtitle),
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant
        )

        Spacer(Modifier.height(28.dp))

        // Auth method selector
        Row(
            Modifier
                .fillMaxWidth()
                .clip(RoundedCornerShape(16.dp))
                .background(MaterialTheme.colorScheme.surfaceVariant)
                .padding(4.dp)
        ) {
            AuthMethodChip(
                label = "Email",
                icon = Icons.Outlined.Email,
                selected = authMethod == AuthMethod.EMAIL,
                modifier = Modifier.weight(1f),
                onClick = { authMethod = AuthMethod.EMAIL }
            )
            AuthMethodChip(
                label = "Phone",
                icon = Icons.Outlined.Phone,
                selected = authMethod == AuthMethod.PHONE,
                modifier = Modifier.weight(1f),
                onClick = { authMethod = AuthMethod.PHONE }
            )
        }

        Spacer(Modifier.height(20.dp))

        // Login / Sign Up tabs
        Row(
            Modifier
                .fillMaxWidth()
                .clip(RoundedCornerShape(16.dp))
                .background(MaterialTheme.colorScheme.surfaceVariant)
                .padding(4.dp)
        ) {
            AuthTab(t(S.loginTab), isLogin, Modifier.weight(1f)) { isLogin = true }
            AuthTab(t(S.signupTab), !isLogin, Modifier.weight(1f)) { isLogin = false }
        }

        Spacer(Modifier.height(24.dp))

        // Auth error
        if (authError != null) {
            Box(
                Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(12.dp))
                    .background(Color(0xFFFEE2E2))
                    .padding(12.dp)
            ) {
                Text(
                    authError,
                    style = MaterialTheme.typography.bodySmall,
                    color = Color(0xFFDC2626)
                )
            }
            Spacer(Modifier.height(16.dp))
        }

        when (authMethod) {
            AuthMethod.EMAIL -> EmailAuthFields(
                isLogin = isLogin,
                email = email,
                password = password,
                name = name,
                passwordVisible = passwordVisible,
                onEmailChange = { email = it },
                onPasswordChange = { password = it },
                onNameChange = { name = it },
                onTogglePassword = { passwordVisible = !passwordVisible }
            )
            AuthMethod.PHONE -> PhoneAuthFields(
                phone = phone,
                onPhoneChange = { if (it.length <= 10) phone = it.filter(Char::isDigit) }
            )
        }

        Spacer(Modifier.height(24.dp))

        // Primary button
        val canSubmit = when (authMethod) {
            AuthMethod.EMAIL -> email.isNotBlank() && password.length >= 6 && (isLogin || name.isNotBlank())
            AuthMethod.PHONE -> phone.length == 10
        }

        PrimaryGradientButton(
            text = if (isLoading) "Please wait..." else if (authMethod == AuthMethod.PHONE) "Send OTP" else if (isLogin) t(S.loginTab) else t(S.signupTab),
            enabled = canSubmit && !isLoading,
            onClick = {
                when (authMethod) {
                    AuthMethod.EMAIL -> onContinueWithEmail(email.trim(), name.trim().ifBlank { email.substringBefore('@') })
                    AuthMethod.PHONE -> onContinueWithPhone(phone)
                }
            },
            modifier = Modifier.fillMaxWidth()
        )

        // Loading indicator
        if (isLoading) {
            Spacer(Modifier.height(12.dp))
            CircularProgressIndicator(
                modifier = Modifier.size(24.dp),
                strokeWidth = 2.dp,
                color = HeroGreen
            )
        }

        Spacer(Modifier.height(20.dp))

        // Divider
        Row(verticalAlignment = Alignment.CenterVertically) {
            Box(Modifier.weight(1f).height(1.dp).background(MaterialTheme.colorScheme.outline))
            Text("  ${t(S.orContinue)}  ", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
            Box(Modifier.weight(1f).height(1.dp).background(MaterialTheme.colorScheme.outline))
        }
        Spacer(Modifier.height(16.dp))

        // Switch auth method hint
        Row(
            Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            SocialButton(
                text = if (authMethod == AuthMethod.PHONE) "Use Email" else "Use Phone",
                modifier = Modifier.weight(1f),
                onClick = {
                    authMethod = if (authMethod == AuthMethod.PHONE) AuthMethod.EMAIL else AuthMethod.PHONE
                }
            )
            SocialButton(
                text = if (isLogin) "New? Sign Up" else "Have account?",
                modifier = Modifier.weight(1f),
                onClick = { isLogin = !isLogin }
            )
        }

        Spacer(Modifier.weight(1f))
        Spacer(Modifier.height(12.dp))

        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(6.dp),
            modifier = Modifier.padding(bottom = 20.dp)
        ) {
            Icon(Icons.Outlined.Lock, contentDescription = null, tint = HeroGreen, modifier = Modifier.size(16.dp))
            Text(
                t(S.trustBadge),
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                textAlign = TextAlign.Center
            )
        }
    }
}

private enum class AuthMethod { EMAIL, PHONE }

@Composable
private fun EmailAuthFields(
    isLogin: Boolean,
    email: String,
    password: String,
    name: String,
    passwordVisible: Boolean,
    onEmailChange: (String) -> Unit,
    onPasswordChange: (String) -> Unit,
    onNameChange: (String) -> Unit,
    onTogglePassword: () -> Unit
) {
    if (!isLogin) {
        FieldLabel("Your Name")
        HeroTextField(value = name, onValueChange = onNameChange, placeholder = "e.g. Priya Sharma")
        Spacer(Modifier.height(16.dp))
    }

    FieldLabel("Email")
    HeroTextField(
        value = email,
        onValueChange = onEmailChange,
        placeholder = "parent@example.com",
        keyboardType = KeyboardType.Email
    )
    Spacer(Modifier.height(16.dp))

    FieldLabel("Password")
    OutlinedTextField(
        value = password,
        onValueChange = onPasswordChange,
        placeholder = { Text("Min 6 characters", color = MaterialTheme.colorScheme.onSurfaceVariant) },
        singleLine = true,
        shape = RoundedCornerShape(14.dp),
        visualTransformation = if (passwordVisible) VisualTransformation.None else PasswordVisualTransformation(),
        trailingIcon = {
            IconButton(onClick = onTogglePassword) {
                Icon(
                    if (passwordVisible) Icons.Outlined.VisibilityOff else Icons.Outlined.Visibility,
                    contentDescription = if (passwordVisible) "Hide password" else "Show password"
                )
            }
        },
        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Password),
        colors = OutlinedTextFieldDefaults.colors(
            focusedBorderColor = MaterialTheme.colorScheme.primary,
            unfocusedBorderColor = MaterialTheme.colorScheme.outline,
            focusedContainerColor = MaterialTheme.colorScheme.surface,
            unfocusedContainerColor = MaterialTheme.colorScheme.surface,
        ),
        modifier = Modifier.fillMaxWidth()
    )

    if (!isLogin) {
        Spacer(Modifier.height(8.dp))
        Text(
            "We'll send a confirmation to your email",
            style = MaterialTheme.typography.bodySmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant
        )
    }
}

@Composable
private fun PhoneAuthFields(
    phone: String,
    onPhoneChange: (String) -> Unit
) {
    FieldLabel("Phone Number")
    Row(verticalAlignment = Alignment.CenterVertically) {
        Box(
            Modifier
                .height(56.dp)
                .clip(RoundedCornerShape(14.dp))
                .background(MaterialTheme.colorScheme.surfaceVariant)
                .padding(horizontal = 16.dp),
            contentAlignment = Alignment.Center
        ) {
            Text("+91", style = MaterialTheme.typography.titleMedium)
        }
        Spacer(Modifier.width(10.dp))
        HeroTextField(
            value = phone,
            onValueChange = onPhoneChange,
            placeholder = "98765 43210",
            keyboardType = KeyboardType.Phone,
            modifier = Modifier.weight(1f)
        )
    }

    Spacer(Modifier.height(8.dp))
    Text(
        "We'll send a 6-digit code via SMS",
        style = MaterialTheme.typography.bodySmall,
        color = MaterialTheme.colorScheme.onSurfaceVariant
    )
}

@Composable
private fun AuthTab(text: String, selected: Boolean, modifier: Modifier = Modifier, onClick: () -> Unit) {
    Box(
        modifier = modifier
            .clip(RoundedCornerShape(12.dp))
            .background(if (selected) MaterialTheme.colorScheme.surface else Color.Transparent)
            .height(44.dp)
            .clickable(onClick = onClick),
        contentAlignment = Alignment.Center
    ) {
        Text(
            text,
            style = MaterialTheme.typography.titleSmall,
            fontWeight = if (selected) FontWeight.SemiBold else FontWeight.Medium,
            color = if (selected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant,
            modifier = Modifier.padding(horizontal = 8.dp)
        )
    }
}

@Composable
private fun AuthMethodChip(
    label: String,
    icon: androidx.compose.ui.graphics.vector.ImageVector,
    selected: Boolean,
    modifier: Modifier = Modifier,
    onClick: () -> Unit
) {
    Row(
        modifier = modifier
            .clip(RoundedCornerShape(12.dp))
            .background(if (selected) MaterialTheme.colorScheme.surface else Color.Transparent)
            .height(44.dp)
            .clickable(onClick = onClick)
            .padding(horizontal = 12.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.Center
    ) {
        Icon(
            icon,
            contentDescription = null,
            tint = if (selected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant,
            modifier = Modifier.size(18.dp)
        )
        Spacer(Modifier.width(6.dp))
        Text(
            label,
            style = MaterialTheme.typography.titleSmall,
            fontWeight = if (selected) FontWeight.SemiBold else FontWeight.Medium,
            color = if (selected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant
        )
    }
}

@Composable
private fun FieldLabel(text: String) {
    Text(
        text,
        style = MaterialTheme.typography.labelLarge,
        color = MaterialTheme.colorScheme.onSurfaceVariant,
        modifier = Modifier
            .fillMaxWidth()
            .padding(bottom = 8.dp)
    )
}

@Composable
fun HeroTextField(
    value: String,
    onValueChange: (String) -> Unit,
    placeholder: String,
    modifier: Modifier = Modifier,
    keyboardType: KeyboardType = KeyboardType.Text
) {
    OutlinedTextField(
        value = value,
        onValueChange = onValueChange,
        placeholder = { Text(placeholder, color = MaterialTheme.colorScheme.onSurfaceVariant) },
        singleLine = true,
        shape = RoundedCornerShape(14.dp),
        keyboardOptions = KeyboardOptions(keyboardType = keyboardType),
        colors = OutlinedTextFieldDefaults.colors(
            focusedBorderColor = MaterialTheme.colorScheme.primary,
            unfocusedBorderColor = MaterialTheme.colorScheme.outline,
            focusedContainerColor = MaterialTheme.colorScheme.surface,
            unfocusedContainerColor = MaterialTheme.colorScheme.surface,
        ),
        modifier = modifier.fillMaxWidth()
    )
}

@Composable
private fun SocialButton(text: String, modifier: Modifier = Modifier, onClick: () -> Unit) {
    Box(
        modifier = modifier
            .height(52.dp)
            .clip(RoundedCornerShape(14.dp))
            .border(1.dp, MaterialTheme.colorScheme.outline, RoundedCornerShape(14.dp))
            .background(MaterialTheme.colorScheme.surface)
            .clickable(onClick = onClick),
        contentAlignment = Alignment.Center
    ) {
        Text(text, style = MaterialTheme.typography.titleSmall, fontWeight = FontWeight.SemiBold)
    }
}

