import androidx.lifecycle.viewmodel.compose.viewModel
import com.rork.vitahero.data.AppViewModel
import com.rork.vitahero.data.NotificationScheduler
import com.rork.vitahero.data.VitaSupabase
import com.rork.vitahero.ui.navigation.AppNavigation
import com.rork.vitahero.data.LocalAppLocale
import com.rork.vitahero.ui.theme.AppTheme
import io.github.jan.supabase.auth.status.SessionStatus

class MainActivity : ComponentActivity() {

    private val notificationPermissionLauncher = registerForActivityResult(
        ActivityResultContracts.RequestPermission()
    ) { /* granted or denied — channels already created, notifs will silently drop if denied */ }

    override fun onCreate(savedInstanceState: Bundle?) {
        enableEdgeToEdge()
        NotificationScheduler.createChannels(this)
        super.onCreate(savedInstanceState)

        // Handle Supabase Auth deeplinks (OTP verification, OAuth callbacks)
        VitaSupabase.handleDeeplinks(intent)

        // Android 13+ requires runtime permission for notifications
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            if (ContextCompat.checkSelfPermission(this, Manifest.permission.POST_NOTIFICATIONS)
                != PackageManager.PERMISSION_GRANTED
            ) {
                notificationPermissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS)
            }
        }

        setContent {
            val appViewModel: AppViewModel = viewModel()
            val state by appViewModel.uiState.collectAsState()

            // Observe Supabase auth session changes
            androidx.compose.runtime.LaunchedEffect(Unit) {
                VitaSupabase.client.auth.sessionStatus.collect { status ->
                    when (status) {
                        is SessionStatus.Authenticated -> {
                            val user = (status as SessionStatus.Authenticated).session.user
                            if (user != null && !appViewModel.isLoggedIn.value) {
                                val phone = user.phone ?: ""
                                val email = user.email ?: ""
                                val name = user.userMetadata?.get("name") as? String
                                    ?: user.userMetadata?.get("full_name") as? String
                                    ?: email.substringBefore('@')
                                appViewModel.onSupabaseLogin(
                                    userId = user.id,
                                    email = email,
                                    phone = phone,
                                    name = name
                                )
                            }
                        }
                        is SessionStatus.NotAuthenticated -> {
                            if (appViewModel.isLoggedIn.value) {
                                appViewModel.logout()
                            }
                        }
                        else -> { /* Loading, etc. */ }
                    }
                }
            }

            androidx.compose.runtime.CompositionLocalProvider(LocalAppLocale provides state.locale) {
                AppTheme(darkTheme = state.darkTheme) {
                    AppNavigation()
                }
            }
        }
    }

    override fun onNewIntent(intent: android.content.Intent) {
        super.onNewIntent(intent)
        // Handle deeplinks when app is already running (singleTask launch mode)
        VitaSupabase.handleDeeplinks(intent)
    }
}

