/** Sign in with email + password via Supabase Auth. */
fun signInWithEmail(email: String, password: String) {
    _authLoading.value = true
    _authError.value = null
    viewModelScope.launch {
        try {
            VitaSupabase.client.auth.signInWith(
                io.github.jan.supabase.auth.providers.builtin.Email
            ) {
                this.email = email
                this.password = password
            }
            // Session will be picked up by MainActivity's auth observer
        } catch (e: Exception) {
            _authError.value = e.message ?: "Sign in failed"
            _authLoading.value = false
        }
    }
}

/** Sign up with email + password + name via Supabase Auth. */
fun signUpWithEmail(email: String, password: String, name: String) {
    _authLoading.value = true
    _authError.value = null
    viewModelScope.launch {
        try {
            VitaSupabase.client.auth.signUpWith(
                io.github.jan.supabase.auth.providers.builtin.Email
            ) {
                this.email = email
                this.password = password
            }
            // Update user metadata with name
            VitaSupabase.client.auth.updateUser {
                data {
                    put("name", name)
                }
            }
            // Session will be picked up by MainActivity's auth observer
        } catch (e: Exception) {
            _authError.value = e.message ?: "Sign up failed"
            _authLoading.value = false
        }
    }
}

/** Send phone OTP via Supabase Auth. */
fun sendPhoneOtp(phone: String) {
    _authLoading.value = true
    _authError.value = null
    viewModelScope.launch {
        try {
            VitaSupabase.client.auth.signInWith(
                io.github.jan.supabase.auth.providers.builtin.OTP
            ) {
                this.phone = "+91$phone"
            }
            _authLoading.value = false
            // OTP sent — user will navigate to OtpScreen
        } catch (e: Exception) {
            _authError.value = e.message ?: "Failed to send OTP"
            _authLoading.value = false
        }
    }
}

/** Verify phone OTP via Supabase Auth. */
fun verifyPhoneOtp(phone: String, token: String) {
    _authLoading.value = true
    _authError.value = null
    viewModelScope.launch {
        try {
            VitaSupabase.client.auth.verifyPhoneOtp(
                phone = "+91$phone",
                token = token
            )
            // Session will be picked up by MainActivity's auth observer
        } catch (e: Exception) {
            _authError.value = e.message ?: "Invalid code"
            _authLoading.value = false
        }
    }
}

fun clearAuthError() {
    _authError.value = null
}

fun clearAuthLoading() {
    _authLoading.value = false
}

